	@Test
	void descriptorScopesAreThreadLocalAndRestoreAfterFailure() throws Exception {
		LmdbNativeEvaluationStrategy strategy = strategy();
		StatementPattern first = new StatementPattern(Var.of("x"), Var.of("p"), Var.of("o"));
		strategy.precompile(first);
		GenericSubplanDescriptor left = GenericSubplanDescriptor.create(first, strategy);
		StatementPattern second = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("x"));
		strategy.precompile(second);
		GenericSubplanDescriptor right = GenericSubplanDescriptor.create(second, strategy);
		LmdbNativeEvaluationStrategy view = strategy.genericOnlyView();
		CountDownLatch entered = new CountDownLatch(2);
		CountDownLatch release = new CountDownLatch(1);
		ExecutorService pool = Executors.newFixedThreadPool(2);
		try {
			Future<Integer> leftMask = pool.submit(() -> left.prepare(() -> {
				entered.countDown();
				await(release);
				return view.valuePositionMasks(left.pinnedExpr()).get("x");
			}));
			Future<Integer> rightMask = pool.submit(() -> right.prepare(() -> {
				entered.countDown();
				await(release);
				return view.valuePositionMasks(right.pinnedExpr()).get("x");
			}));
			assertThat(entered.await(10, TimeUnit.SECONDS)).isTrue();
			release.countDown();
			assertThat(leftMask.get(10, TimeUnit.SECONDS)).isEqualTo(1);
			assertThat(rightMask.get(10, TimeUnit.SECONDS)).isEqualTo(4);
		} finally {
			release.countDown();
			pool.shutdownNow();
		}
		assertThatThrownBy(() -> left.prepare(() -> {
			throw new IllegalStateException("preparation failed");
		})).isInstanceOf(IllegalStateException.class);
		assertThat(strategy.valuePositionMasks(second).get("x")).isEqualTo(4);
	}

	private static void await(CountDownLatch latch) {
		try {
			assertThat(latch.await(10, TimeUnit.SECONDS)).isTrue();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError(e);
		}
	}

