	@Test
	void directPrecompilePreparesValuesBeforePositionAnalysis() {
		assertOneShotValuesPrepared(false);
	}

	@Test
	void optimizationPreparesValuesBeforePositionAnalysis() {
		assertOneShotValuesPrepared(true);
	}

	private static void assertOneShotValuesPrepared(boolean optimize) {
		AtomicInteger traversals = new AtomicInteger();
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingSets(() -> {
			if (traversals.incrementAndGet() != 1) {
				throw new IllegalStateException("VALUES iterable may be traversed only once");
			}
			return List.<BindingSet>of(new ListBindingSet(List.of("seed"), VF.createLiteral(1))).iterator();
		});
		Var left = Var.of("x");
		Var right = Var.of("parserEndpoint", true);
		QueryRoot root = new QueryRoot(new Filter(new Join(values,
				new StatementPattern(left, Var.of("p"), right)), new SameTerm(left.clone(), right.clone())));
		LmdbNativeEvaluationStrategy strategy = strategy();
		if (optimize) {
			strategy.optimize(root, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		} else {
			strategy.precompile(root);
		}
		assertThat(traversals.get()).isEqualTo(1);
		assertThat(strategy.valuePositionMasks(root).get("x")).isEqualTo(5);
	}

	@Test
	void scalarAndBatchReadersDecodeThroughTheirSlotPositions() {
		RecordingSource source = new RecordingSource();
		TupleExpr query = new SPARQLParser().parseQuery("SELECT ?a WHERE { ?a a ?a }", "urn:test:").getTupleExpr();
		NativeSlotLayout layout = layout(
				Map.of("a", NativeValuePositionAnalysis.analyze(query).masksFor(query).get("a")));
		assertThat(layout.positionMask(0)).isEqualTo(5);
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		long id = integerId(7);
		row.replaceSlot(0, id);
		LmdbNativeValueCodec.DecodedValue expected = source.codec.decode(id, 5);
		assertThat(row.decodedValue(0, source.codec, false)).isSameAs(expected);
		NativeBatch batch = new NativeBatch(1, 2);
		batch.set(0, 0, id);
		batch.finishRows(1);
		LmdbNativeCompiledBoolean filter = new LmdbNativeCompiledBoolean(1L, reader -> {
			assertThat(reader.positionMask(0)).isEqualTo(5);
			assertThat(reader.decodedValue(0, source.codec, false)).isSameAs(expected);
			return LmdbNativeTruth.TRUE;
		});
		assertThat(filter.selectBatch(batch, batch.selection, 1, row)).isEqualTo(1);
	}

	@Test
	void lazyRowsAndCompactedProjectionRetainCompleteImmutableMasks() {
		RecordingSource source = new RecordingSource();
		NativeSlotLayout layout = layout(Map.of("x", 5));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		row.replaceSlot(0, integerId(7));
		assertThat(row.view.getValue("x")).isNotNull();
		assertThat(source.masks).containsExactly(5);
		source.masks.clear();
		String[] names = { "x", "x", "y" };
		int[] compactSlots = { 1, 0, 2 };
		int[] masks = { 1, 4, 2 };
		NativeProjectedBindingSet.ProjectionLayout projection = NativeProjectedBindingSet.ProjectionLayout
				.create(names, compactSlots, masks);
		names[0] = "changed";
		compactSlots[0] = 2;
		masks[0] = 8;
		NativeProjectedBindingSet result = new NativeProjectedBindingSet(source, projection,
				new long[] { integerId(7), integerId(8), integerId(7) });
		assertThat(result.getValue("x")).isNotNull();
		assertThat(result.getValue("y")).isNotNull();
		assertThat(source.masks).containsExactly(5, 2);
	}

