	private static NativeSlotLayout layout(Map<String, Integer> masks) {
		Map<String, Integer> slots = new LinkedHashMap<>();
		for (String name : masks.keySet()) {
			slots.put(name, slots.size());
		}
		NativeSlotLayout layout = new NativeSlotLayout(slots, null);
		layout.positionMasks(masks, masks);
		layout.freeze(new ArrayList<>(slots.keySet()));
		return layout;
	}

	private static long integerId(long value) {
		return ValueIds.createId(ValueIds.T_INTEGER, (value << 1) ^ (value >> 63));
	}

	private static LmdbNativeEvaluationStrategy strategy() {
		TripleSource source = new TripleSource() {
			@Override
			public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
					Resource... contexts) {
				return new EmptyIteration<>();
			}

			@Override
			public ValueFactory getValueFactory() {
				return VF;
			}
		};
		return new LmdbNativeEvaluationStrategy(source, null, null, 0L, new EvaluationStatistics(), false);
	}

